local _, addon = ...

addon.localeData.enUS.raceClassTexts = {Skyborne={DRUID={HELLO={ziel={"Wind and wilds have led you here, %s. Welcome."},gruppe={"Wind and wilds have brought us together. Welcome."}},WAVE={ziel={"May the wind carry the wilds' greeting to you, %s."},gruppe={"May the wind carry the wilds' greeting to you all."}},SALUTE={ziel={"Foresight, balance, and my respect, %s."},gruppe={"Foresight, balance, and my respect."}},BOW={ziel={"I bow to your path, %s. No tree grows without sky."},gruppe={"No tree grows without sky. My respect to you all."}},LAUGH={ziel={"Ha! Even the leaves are shaking with laughter, %s."},gruppe={"Ha! Even the leaves are shaking with laughter."}},DANCE={ziel={"Dance with me, %s. The wind moves the leaves; we do the rest."},gruppe={"The wind moves the leaves; we do the rest."}},SIT={ziel={"Sit, %s. Roots do not grow in flight."},gruppe={"Roots do not grow in flight. Time for a rest."}},SLEEP={ziel={"Sleep well, %s. May the wind in the branches watch over you."},gruppe={"May the wind in the branches watch over us."}},THANK={ziel={"Thank you, %s. May wind and wilds repay your kindness."},gruppe={"Thank you. May wind and wilds repay your kindness."}}}}}
